var currentStep = 0;
var steps;
var progress="" ;
var step__diff=0;
var total_steps; /*No. of total steps*/

$(document).ready(function(){
	var pgbar = document.getElementsByClassName('progress__bar')[0];
    if(pgbar){
		progress = document.getElementsByClassName('progress__complete')[0];
        var pgbar__hr = document.getElementsByClassName('progress__bar__hr')[0];
        steps = document.getElementsByClassName('progress-step');
        steps[0].classList.add('active');
        total_steps = steps.length; /*No. of total steps*/
        var pgbar__width__str=window.getComputedStyle(pgbar__hr,null).width;
        var pgbar__width = (+pgbar__width__str.replace('px', ''));
        var first__step__content=document.getElementsByClassName('progress__step')[0];
        var first__step__width = +(window.getComputedStyle(first__step__content, null).width).replace('px','');
        var last__step__content=document.getElementsByClassName('progress__step')[total_steps-1];
        var last__step__width = +(window.getComputedStyle(last__step__content, null).width).replace('px','');
        pgbar__width -=((first__step__width+last__step__width)/2);
        pgbar__hr.style.width=pgbar__width.toString()+"px";
        pgbar__hr.style.left=(first__step__width/2).toString()+"px";
        progress.style.left=(first__step__width/2).toString()+"px";
    }

});

function moveNext(){
    if (currentStep < total_steps - 1) {
        steps[currentStep].classList.add('completed');
        steps[currentStep].classList.remove('active');
        currentStep++;
        var step__inc = document.getElementsByClassName('icon-circle')[currentStep-1];
        var curr__step__inc = document.getElementsByClassName('icon-circle')[currentStep];
        step__diff += curr__step__inc.getBoundingClientRect().x-step__inc.getBoundingClientRect().x;
        progress.style.width = (step__diff).toString() + "px";
        steps[currentStep].classList.add('active');
    }
};

function movePrevious(isDefaultSelected){
    if (currentStep > 0) {

        if(isDefaultSelected) {
			steps[0].classList.add('active');
        }

        steps[currentStep].classList.remove('active');
        currentStep--;
		var step__inc = document.getElementsByClassName('icon-circle')[currentStep];
        var curr__step__inc = document.getElementsByClassName('icon-circle')[currentStep+1];
        step__diff -= Math.abs(curr__step__inc.getBoundingClientRect().x-step__inc.getBoundingClientRect().x);
        progress.style.width = (step__diff).toString() + "px";
        steps[currentStep].classList.remove('completed');
    }
};